# ----------------------------------------------------------------------------- formatting
def _fmt(x, kind: str, inf: str = "∞") -> str:
    if isinstance(x, (int, float, np.floating)) and not isinstance(x, (bool, np.bool_)) and np.isinf(float(x)):
        return inf if x > 0 else "-" + inf
    if x is None or (isinstance(x, float) and not math.isfinite(x)) or (not isinstance(x, str) and pd.isna(x)):
        return "NA"
    if isinstance(x, (bool, np.bool_)):
        return "yes" if x else "no"
    if kind == "str":
        return str(x)
    x = float(x)
    if kind == "int":
        return f"{int(round(x)):,}"
    if kind.startswith("r") and kind[1:].isdigit():
        return f"{x:.{int(kind[1:])}f}"
    if kind == "p":
        return S.fmt_p(x, 2, latex=False).replace("e-0", "e-").replace("e+00", "")
    if kind.startswith("e") and kind[1:].isdigit():
        if x == 0:
            return "0"
        return f"{x:.{int(kind[1:]) - 1}e}".replace("e-0", "e-").replace("e+0", "e+")
    if kind.startswith("sig") and kind[3:].isdigit():
        return S.fmt_sig(x, int(kind[3:]))
    if kind.startswith("pct") and kind[3:].isdigit():
        return f"{100 * x:.{int(kind[3:])}f}%"
    return f"{x:g}"


@dataclass
class Fact:
    id: str
    label: str
    csv: str
    query: str | None
    col: str
    fmt: str = "r2"
    lo: str | None = None
    hi: str | None = None
    ci: str | None = None          # what the interval is (e.g. '95% CrI')
    se: str | None = None          # standard-error column (printed as +/- SE)
    agg: str | None = None         # None | min | max | sum | mean | count | range | first | nunique
    by: str | list | None = None   # group column(s): value listed per group
    order: str | None = None       # sort groups by this column (default: universe order, then name)
    mult: float | None = None      # unit conversion applied to value and interval (e.g. bytes -> GiB)
    inf: str = "∞"                 # text printed for an infinite value
    se_label: str = "SE"           # what the +/- column is (e.g. 'Monte Carlo SD')
    derive: object = None          # callable(selected rows) -> float: a value computed from several cells
    # filled by evaluate()
    value: str = ""
    full: str = ""
    status: str = ""
    error: str = ""

    @property
    def provenance(self) -> str:
        q = self.query if self.query else "all rows"
        cols = self.col + (f" [{self.lo}, {self.hi}]" if self.lo else "") + (f" ± {self.se}" if self.se else "")
        by = f"; by {self.by if isinstance(self.by, str) else '/'.join(self.by)}" if self.by else ""
        agg = f"; {self.agg}" if self.agg else ""
        der = f"; derived: {self.derive.__doc__}" if self.derive is not None and self.derive.__doc__ else ""
        return f"`{self.csv}` · `{q}` · `{cols}`{by}{agg}{der}"


class _Tables:
    def __init__(self):
        self.cache: dict[str, pd.DataFrame] = {}
        self.used: dict[str, set] = {}

    def get(self, name: str) -> pd.DataFrame:
        if name not in self.cache:
            self.cache[name] = pd.read_csv(S.TABLES / name, low_memory=False)
        return self.cache[name]


def _status(sel: pd.DataFrame, cols: list[str]) -> str:
    out = []
    if "analysis_status" in sel.columns:
        st = set(sel["analysis_status"].dropna().astype(str))
        if "post_hoc" in st:
            out.append("post hoc" if len(st) == 1 else "partly post hoc")
    if "post_hoc_columns" in sel.columns:
        ph = set()
        for v in sel["post_hoc_columns"].dropna().astype(str):
            ph |= {c.strip() for c in v.split(";")}
        if any(c in ph or any(p.endswith("*") and c.startswith(p[:-1]) for p in ph) for c in cols if c):
            out.append("post hoc column")
    return ", ".join(dict.fromkeys(out))


def _one(sel: pd.DataFrame, f: Fact) -> tuple[str, str]:
    """Value and value-with-interval for one selection (no grouping)."""
    if f.col not in sel.columns:
        raise KeyError(f"column {f.col!r} not in {f.csv}")
    if f.derive is not None:
        x = f.derive(sel)
        v = x if isinstance(x, str) else _fmt(float(x), f.fmt, f.inf)
        return v, v
    vals = sel[f.col]
    if f.agg is None or f.agg == "first":
        if f.agg is None and len(sel) > 1:
            cols = [c for c in (f.col, f.lo, f.hi, f.se) if c]
            uniq = sel[cols].drop_duplicates()
            if len(uniq) > 1:
                raise ValueError(f"{len(sel)} rows with {len(uniq)} distinct value/interval combinations "
                                 "(ambiguous filter)")
        row = sel.iloc[0]
        m = f.mult if f.mult is not None else 1.0

        def g(c):
            x = row[c]
            if f.mult is not None and not pd.isna(x):
                return float(x) * m
            return x

        v = _fmt(g(f.col), f.fmt, f.inf)
        if f.fmt == "str" and isinstance(g(f.col), str):
            v = _disp(v)
        full = v
        if f.lo and f.hi and S.finite(row[f.lo]) and S.finite(row[f.hi]):
            full = f"{v} [{_fmt(g(f.lo), f.fmt)}, {_fmt(g(f.hi), f.fmt)}]"
        if f.se and S.finite(row[f.se]):
            full = f"{v} ± {_fmt(g(f.se), f.fmt)} ({f.se_label})"
        return v, full
    if f.agg == "range":
        v = f"{_fmt(vals.min(), f.fmt)} to {_fmt(vals.max(), f.fmt)}"
        return v, v
    if f.agg == "count":
        return _fmt(len(sel), "int"), _fmt(len(sel), "int")
    if f.agg == "nunique":
        return _fmt(vals.nunique(), "int"), _fmt(vals.nunique(), "int")
    if f.agg == "n_true":
        n = int(vals.map(S.as_bool).sum())
        return f"{n} of {len(vals)}", f"{n} of {len(vals)}"
    if f.agg == "join":
        v = "; ".join(str(x) for x in vals.dropna().astype(str))
        return v, v
    x = getattr(vals.astype(float), f.agg)()
    v = _fmt(x, f.fmt)
    return v, v


