def _disp(x: str) -> str:
    if x in S.UNIVERSE_LABEL:
        return S.UNIVERSE_LABEL[x]
    if x in DISPLAY:
        return DISPLAY[x]
    if x in S.SCORE_STYLE:
        return S.SCORE_STYLE[x].label
    if x in S.REFERENCE_LABEL:
        return S.REFERENCE_LABEL[x]
    if x in S.FAMILY_LABEL:
        return S.FAMILY_LABEL[x]
    if x.startswith("study:"):
        return S.REFERENCE_LABEL.get(x[len("study:"):], x[len("study:"):])
    for pre, txt in (("gap_ge_real_", "gap ≥ real {} gap"), ("logistic_at_real_gap_", "at the real {} gap"),
                     ("real_gap_", "real {} gap")):
        if x.startswith(pre) and x[len(pre):] in S.UNIVERSE_LABEL:
            return txt.format(S.UNIVERSE_LABEL[x[len(pre):]].lower())
    m = re.fullmatch(r"(.+)_top(\d+)", x)
    if m:
        return f"{_disp(m.group(1))} (top {m.group(2)})"
    if " + " in x or "restarts run" in x:
        return x.replace("a/", "").replace("b/", "")
    return x


def _order_key(val):
    order = {u: i for i, u in enumerate(S.UNIVERSE_ORDER + ["all_tissues"])}
    return order.get(val, 100), str(val)


def evaluate(f: Fact, T: _Tables) -> Fact:
    try:
        path = S.TABLES / f.csv
        if not path.exists():
            raise FileNotFoundError(f"{f.csv} not found")
        df = T.get(f.csv)
        sel = df.query(f.query, engine="python") if f.query else df
        if sel.empty:
            raise ValueError("filter selects no rows")
        T.used.setdefault(f.csv, set()).add(f.id)
        f.status = _status(sel, [f.col, f.lo, f.hi])
        if f.by:
            by = [f.by] if isinstance(f.by, str) else list(f.by)
            parts_v, parts_f = [], []
            if f.order:
                sel = sel.sort_values(f.order)
            keys = list(dict.fromkeys(map(tuple, sel[by].astype(str).values.tolist())))
            if not f.order:
                keys.sort(key=lambda k: tuple(_order_key(x) for x in k))
            for k in keys:
                m = np.ones(len(sel), bool)
                for c, kv in zip(by, k):
                    m &= (sel[c].astype(str) == kv).values
                v, full = _one(sel[m], f)
                lab = "/".join(_disp(x) for x in k)
                parts_v.append(f"{lab} {v}")
                parts_f.append(f"{lab} {full}")
            f.value, f.full = "; ".join(parts_v), "; ".join(parts_f)
        else:
            f.value, f.full = _one(sel, f)
    except Exception as e:  # noqa: BLE001 - every failure is reported, never hidden
        f.error = f"{type(e).__name__}: {e}"
        f.value = f.full = "MISSING"
    return f


class _Missing(dict):
    def __missing__(self, key):
        return f"MISSING[{key}]"


# ----------------------------------------------------------------------------- derived values
# A derived fact combines several cells of the selected rows; its docstring is printed in the provenance.
GAP_SAFE = 5.0     # nats: lower edge of the gap bins of posterior_modes above which no misselection occurred
FAITHFUL = "simulator in ['faithful_cc', 'faithful_cc_strat']"


def _d_one_minus(sel):
    """1 − value (misselection rate = 1 − P(dominant optimum = truth))"""
    return 1.0 - float(sel["value"].iloc[0])


def _d_lr_bound(sel):
    """P(truth ahead by ≥ the real immune gap | truth = dominant optimum) / Wilson upper bound of P(other optimum
    ahead by ≥ that gap | truth = second optimum): bound-based likelihood ratio of the real gap"""
    a = sel.loc[sel.universe == "immune", "value"]
    b = sel.loc[sel.universe == "immune_truthmode1", "ci_hi"]
    return float(a.iloc[0]) / float(b.iloc[0])


def _d_realised_over_claimed(sel):
    """realised / claimed Strong FDR (dominant_strong_realised_fdr_mean / dominant_strong_claimed_bfdr_mean)"""
    r = sel.loc[sel.quantity == "dominant_strong_realised_fdr_mean", "value"]
    c = sel.loc[sel.quantity == "dominant_strong_claimed_bfdr_mean", "value"]
    return float(r.iloc[0]) / float(c.iloc[0])


def _d_hub_ratio(sel):
    """realised FDR / estimated BFDR of the Family-HB BFDR set (metric fdr / metric bfdr_estimated)"""
    return float(sel.loc[sel.metric == "fdr", "mean"].iloc[0]) / float(sel.loc[sel.metric == "bfdr_estimated", "mean"].iloc[0])


def _d_switch_only_mean(sel):
    """mean D over the identified lineage configurations in which Family-HB switches mode:
    (n·D over all identified − n·D over identified without switch) / (difference of the n)"""
    a = sel[sel.subset == "excl_uninformative"].iloc[0]
    b = sel[sel.subset == "excl_uninformative_no_fhb_mode_switch"].iloc[0]
    n = float(a.n_configs) - float(b.n_configs)
    return (float(a.n_configs) * float(a.mean_D) - float(b.n_configs) * float(b.mean_D)) / n


def _d_p2_range(sel):
    """smallest to largest bridge estimate of the second-mode probability over draw sets and proposals"""
    r = sel.iloc[0]
    return (f"{_fmt(r['p2_range_draw_sets_proposals_lo'], 'e2')} to "
            f"{_fmt(r['p2_range_draw_sets_proposals_hi'], 'e2')}")


def _d_gap_safe(sel):
    """the constant GAP_SAFE of digest.py (a gap-bin edge of posterior_modes), in nats"""
    return GAP_SAFE


def _ge_gap_counter(thr: float):
    """Derived value 'k of n': replicates with a gap of at least ``thr`` nats (n) and among them those whose
    dominant optimum is the truth (k)."""
    def f(sel):
        g = sel[sel["gap"].astype(float) >= thr]
        k = int(g["dominant_is_truth"].map(S.as_bool).sum())
        return f"{k} of {len(g)}"
    f.__doc__ = f"replicates with gap ≥ {thr:.2f} nats whose dominant optimum is the truth (k of n)"
    return f


def _real_gap(universe: str) -> float:
    """Real log-posterior gap of the Family-HB fit (fit_convergence.csv), used as a replicate filter."""
    try:
        c = pd.read_csv(S.TABLES / "fit_convergence.csv", low_memory=False)
        return float(c[(c.fit_id == "family_hb") & (c.universe == universe)]["gap_to_next_optimum"].iloc[0])
    except Exception:  # noqa: BLE001 - a missing table makes the dependent fact MISSING, not the build fail
        return float("inf")


