# ----------------------------------------------------------------------------- assets
def discover_assets() -> dict[str, set]:
    """Map every generated table/figure to the CSV files named in its provenance."""
    out: dict[str, set] = {}
    pat = re.compile(r"\b([A-Za-z0-9_]+\.csv)\b")
    def _csvs(text: str) -> set:
        text = text.replace("\\_", "_")                     # LaTeX-escaped underscores
        return {c for c in pat.findall(text) if (S.TABLES / c).exists()}

    if S.TAB_DIR.exists():
        for p in sorted(S.TAB_DIR.glob("*.tex")):
            out[f"tables/{p.name}"] = _csvs(p.read_text(errors="ignore"))
    if S.FIG_DIR.exists():
        for p in sorted(S.FIG_DIR.glob("*.pdf")):
            csvs = set()
            for side in S.FIG_DIR.glob(p.stem + "*.txt"):
                csvs |= _csvs(side.read_text(errors="ignore"))
            for side in S.FIG_DIR.glob(p.stem + "*.json"):
                csvs |= _csvs(side.read_text(errors="ignore"))
            if p.stem in FSUP.FIGURE_SOURCES:
                csvs |= set(FSUP.FIGURE_SOURCES[p.stem])
            out[f"figures/{p.name}"] = csvs
    for name, srcs in FSUP.FIGURE_SOURCES.items():
        out.setdefault(f"figures/{name}.pdf (supplementary; not yet built)" if not (S.FIG_DIR / f"{name}.pdf").exists()
                       else f"figures/{name}.pdf", set(srcs))
    return out


def _is_regenerated(csv: str) -> bool:
    return any(re.search(p, csv) for p in REGENERATED_PATTERNS)


def freshness(csvs: set[str]) -> list[dict]:
    rows = []
    for c in sorted(csvs):
        p = S.TABLES / c
        if not p.exists():
            rows.append({"csv": c, "mtime": "missing", "regenerated": _is_regenerated(c), "stale": True})
            continue
        m = dt.datetime.fromtimestamp(p.stat().st_mtime)
        rows.append({"csv": c, "mtime": m.strftime("%Y-%m-%d %H:%M"), "regenerated": _is_regenerated(c),
                     "stale": _is_regenerated(c) and m < FRESHNESS_CUTOFF})
    return rows


def _reports_present() -> dict[str, str]:
    out = {}
    for name in ["evalfix_REPORT.txt", "modes_REPORT.txt", "modes2_REPORT.txt", "robfix_REPORT.txt", "heldfix_REPORT.txt",
                 "pipeline_REPORT.txt", "assets2_ROB_READY"]:
        p = S.REPORTS / name
        if p.exists():
            m = dt.datetime.fromtimestamp(p.stat().st_mtime)
            out[name] = m.strftime("%Y-%m-%d %H:%M") + (" (after cut-off)" if m > FRESHNESS_CUTOFF else " (BEFORE cut-off)")
        else:
            out[name] = "absent"
    return out


# ----------------------------------------------------------------------------- rendering
def build_facts() -> tuple[dict[str, list[Fact]], dict[str, Fact], _Tables]:
    T = _Tables()
    facts = _facts()
    flat: dict[str, Fact] = {}
    for sec, lst in facts.items():
        for f in lst:
            if f.id in flat:
                raise ValueError(f"duplicate fact id {f.id}")
            evaluate(f, T)
            flat[f.id] = f
    return facts, flat, T


def _fact_line(f: Fact) -> str:
    st = f" — *{f.status}*" if f.status else ""
    ci = f" ({f.ci})" if (f.ci and f.lo) else ""
    err = f" — **problem: {f.error}**" if f.error else ""
    return f"- **{f.id}** — {f.label}: **{f.full}**{ci}{st}  \n  provenance: {f.provenance}{err}"


def render_digest(facts, flat, T, assets) -> tuple[str, list[str]]:
    V = _Missing({k: f.value for k, f in flat.items()})
    C = _Missing({k: f.full for k, f in flat.items()})
    problems = [f"`{f.id}` ({f.csv}): {f.error}" for f in flat.values() if f.error]
    used = set(T.used)
    fr = freshness(used | {c for s in assets.values() for c in s})
    stale = [r["csv"] for r in fr if r["stale"]]
    now = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    L = []
    L.append("# Results digest: SAGMB R2 (multi-reference latent-truth modelling)\n")
    L.append(f"Generated {now} by `src/r2/paper_assets/digest.py` from `data/r2/tables/*.csv`. "
             "Every number below is read from a CSV by the script; each fact lists its provenance as "
             "`file` · `row filter (pandas query)` · `column [interval columns]`. Interpretive text is a "
             "template filled from the same facts. Analyses flagged post hoc in the CSVs are marked *post hoc*.\n")
    L.append("Interval conventions: TF-bootstrap = TF-cluster percentile bootstrap; CrI = posterior credible "
             "interval; Wilson = Wilson score interval; t CI = t interval over simulation replicates; SE = standard error.\n")
    rp = _reports_present()
    L.append("## Data freshness\n")
    L.append("Reports of the modules regenerating tables: " + "; ".join(f"`{k}`: {v}" for k, v in rp.items()) + ".\n")
    L.append(f"Tables regenerated after the cut-off {FRESHNESS_CUTOFF:%Y-%m-%d %H:%M} are expected for: "
             "`heldout_*` (except `heldout_chip_*`), `rep_leavek.csv`, `tune_*`, `modes_*`, `rob_*`, `fit_recovery*`, "
             "`pipeline_*`.\n")
    if stale:
        L.append("**STALE inputs (older than the cut-off):** " + ", ".join(f"`{c}`" for c in stale) + ".\n")
        dep_f = sorted({fid for c in stale for fid in T.used.get(c, set())})
        dep_a = sorted(a for a, s in assets.items() if s & set(stale))
        L.append("Facts depending on stale tables: " + (", ".join(f"`{x}`" for x in dep_f) or "none") + ".\n")
        L.append("Assets depending on stale tables: " + (", ".join(f"`{x}`" for x in dep_a) or "none") + ".\n")
    else:
        L.append("No stale inputs: every regenerated table used here is newer than the cut-off.\n")
    L.append("| CSV | modified | regenerated by another module | stale |\n|---|---|---|---|")
    for r in fr:
        L.append(f"| `{r['csv']}` | {r['mtime']} | {'yes' if r['regenerated'] else 'no'} | {'**yes**' if r['stale'] else 'no'} |")
    L.append("")
    if problems:
        L.append("## Problems\n")
        L.extend(f"- {p}" for p in problems)
        L.append("")
    for sec, title, qs in SECTIONS:
        L.append(f"## {sec} {title}\n")
        L.append(f"Reviewer points: {', '.join(qs)}.\n")
        L.append("### Key quantitative facts\n")
        for f in facts[sec]:
            L.append(_fact_line(f))
        L.append("")
        pr = PROSE.get(sec, {})
        L.append("### Interpretation\n")
        for para in pr.get("interp", []):
            L.append(para.format(V=V, C=C) + "\n")
        L.append("### Caveats\n")
        for c in pr.get("caveats", []):
            L.append("- " + c.format(V=V, C=C))
        L.append("")
        sec_csvs = {f.csv for f in facts[sec]}
        sup = sorted(a for a, s in assets.items() if s & sec_csvs)
        L.append("### Supporting tables and figures\n")
        if sup:
            for a in sup:
                hit = sorted(assets[a] & sec_csvs)
                flag = " (STALE input)" if set(hit) & set(stale) else ""
                L.append(f"- `paper/r2/{a}` — uses {', '.join(f'`{h}`' for h in hit)}{flag}")
        else:
            L.append("- none generated yet")
        L.append("")
    L.append("## Asset index\n")
    L.append("Every generated table and figure with the CSV files named in its provenance "
             "(stale inputs marked).\n")
    for a in sorted(assets):
        srcs = sorted(assets[a])
        mark = " — **depends on stale input**" if set(srcs) & set(stale) else ""
        L.append(f"- `paper/r2/{a}`: {', '.join(f'`{c}`' for c in srcs) or 'no CSV named'}{mark}")
    L.append("")
    return "\n".join(L) + "\n", problems


def _reviewer_titles() -> dict[str, str]:
    """{'Q1': title line of point Q1, ...} from paper/r2/letter_quotes.tex (written by letter_numbers.py)."""
    if not QUOTES.exists():
        return {}
    text = QUOTES.read_text(encoding="utf-8")
    unesc = [("\\textbackslash{}", "\\"), ("\\_", "_"), ("\\%", "%"), ("\\&", "&"), ("\\#", "#"),
             ("\\$", "$"), ("\\{", "{"), ("\\}", "}"), ("\\textasciitilde{}", "~"), ("\\textasciicircum{}", "^")]
    out = {}
    for n, val in re.findall(r"\\csname revqt@(\d+)\\endcsname\{(.*)\}$", text, flags=re.M):
        for a, b in unesc:
            val = val.replace(a, b)
        out[f"Q{n}"] = val
    return out


def render_reviewer(flat, assets) -> str:
    titles = _reviewer_titles()
    now = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    facts_by_sec = {}
    for sec, lst in _facts_index(flat).items():
        facts_by_sec[sec] = lst
    L = ["# Reviewer 1 (SAGMB.2026.0009.R2): points Q1-Q24 mapped to the evidence\n",
         f"Generated {now} by `src/r2/paper_assets/digest.py`. Point titles are quoted from "
         "`paper/r2/letter_quotes.tex` (Reviewer 1, verbatim); values are the digest facts (see `results_digest.md` "
         "for provenance of every value).\n"]
    for q in [f"Q{i}" for i in range(1, 25)]:
        req = titles.get(q, "(title not found)")
        secs, fids, note = REVIEWER_MAP.get(q, ([], [], ""))
        L.append(f"## {q}: {req}\n")
        L.append(f"*Where answered:* {note}\n")
        if q == "Q24":
            ra = S.SP / "src" / "r2" / "reproduce_all.py"
            L.append(f"*Status at build time:* `src/r2/reproduce_all.py` {'present' if ra.exists() else 'NOT present (pipeline module pending)'}; "
                     f"`src/r2/make_paper_assets.py` {'present' if (S.SP / 'src' / 'r2' / 'make_paper_assets.py').exists() else 'absent'}; "
                     f"`data/r2/MANIFEST.sha256` {'present' if (S.SP / 'data' / 'r2' / 'MANIFEST.sha256').exists() else 'absent'}; "
                     f"`requirements-r2.txt` {'present' if (S.SP / 'requirements-r2.txt').exists() else 'absent'}.\n")
        if secs:
            L.append("*Digest sections:* " + ", ".join(f"{s} ({dict((a, b) for a, b, _ in SECTIONS)[s]})" for s in secs) + "\n")
        if fids:
            L.append("*Key evidence:*\n")
            for fid in fids:
                f = flat.get(fid)
                if f is None:
                    L.append(f"- `{fid}`: MISSING (unknown fact id)")
                else:
                    st = f" — *{f.status}*" if f.status else ""
                    L.append(f"- `{fid}` {f.label}: **{f.full}**{st}")
            L.append("")
        sec_csvs = {flat[f].csv for f in fids if f in flat}
        sup = sorted(a for a, s in assets.items() if s & sec_csvs)
        if sup:
            L.append("*Tables/figures:* " + ", ".join(f"`{a}`" for a in sup) + "\n")
    return "\n".join(L) + "\n"


def _facts_index(flat):
    idx = {}
    for f in flat.values():
        idx.setdefault(f.csv, []).append(f.id)
    return idx


def build(out_dir: Path | None = None) -> dict:
    out_dir = Path(out_dir) if out_dir is not None else S.DIGEST_DIR
    out_dir.mkdir(parents=True, exist_ok=True)
    facts, flat, T = build_facts()
    assets = discover_assets()
    md, problems = render_digest(facts, flat, T, assets)
    (out_dir / "results_digest.md").write_text(md)
    (out_dir / "reviewer_points.md").write_text(render_reviewer(flat, assets))
    n_missing = sum(1 for f in flat.values() if f.error)
    print(f"wrote {out_dir / 'results_digest.md'} ({len(flat)} facts, {n_missing} missing) and reviewer_points.md")
    for p in problems:
        print("  PROBLEM", p)
    return {"facts": flat, "problems": problems, "assets": assets, "tables": T}


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--out-dir", default=None)
    a = ap.parse_args(argv)
    build(Path(a.out_dir) if a.out_dir else None)
    return 0


if __name__ == "__main__":
    main()
